{"command":"python3 -c "
import PyPDF2
import re

# Extract text from PDF
with open('paper.pdf', 'rb') as file:
    reader = PyPDF2.PdfReader(file)
    full_text = ''
    for page in reader.pages:
        try:
            text = page.extract_text()
            if text:
                full_text += text + '\n'
        except:
            pass

print('=== Looking for Figure 7 details ===')

# Search for Figure 7 specifically
figure7_matches = re.findall(r'Figure 7.*?(?=Figure \d+|$)', full_text, re.IGNORECASE | re.DOTALL)
if figure7_matches:
    figure7_text = figure7_matches[0]
    print('Figure 7 content:')
    print(figure7_text[:1000] + '...' if len(figure7_text) > 1000 else figure7_text)

    # Look for time measurements in Figure 7 context
    time_in_figure7 = re.findall(r'(\d+(?:\.\d+)?)\s*ms', figure7_text, re.IGNORECASE)
    if time_in_figure7:
        print(f'\\nTime measurements in Figure 7 context: {time_in_figure7}')

    duration_in_figure7 = re.findall(r'duration.*?(\d+(?:\.\d+)?)\s*ms', figure7_text, re.IGNORECASE)
    if duration_in_figure7:
        print(f'\\nDuration measurements in Figure 7: {duration_in_figure7}')
else:
    print('No Figure 7 found')

print('\\n=== Looking for X-ray time profile context ===')

# Search for X-ray time profile context
xray_profile_context = re.findall(r'X-ray.*?time profile.*?(?=\\n\\n|Figure|$)', full_text, re.IGNORECASE | re.DOTALL)
if xray_profile_context:
    for context in xray_profile_context[:2]:
        print(f'X-ray time profile context: {context[:300]}...')

print('\\n=== Looking for temporal analysis ===')

# Look for temporal analysis sections
temporal_sections = re.findall(r'temporal.*?analysis.*?(?=\\n\\n|\\n[A-Z]|$)', full_text, re.IGNORECASE | re.DOTALL)
if temporal_sections:
    for section in temporal_sections[:2]:
        print(f'Temporal analysis: {section[:300]}...')
""}

